from docx import Document
from docx.shared import Inches, Pt, RGBColor
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from pathlib import Path

OUT = Path(__file__).parent / 'CampusFix_Defense_Reviewer.docx'
sections = [
('A  Problem and justification', [
('What specific problem at East System Colleges of Rizal does CampusFix aim to solve?', 'Ang CampusFix ay naglalayong ayusin ang fragmented na reporting at monitoring ng sirang school facilities at equipment. Kapag verbal o hiwa-hiwalay na messages ang gamit, maaaring kulang ang location details at mahirap malaman kung sino ang may hawak at ano na ang status ng concern. Iminumungkahi namin ang isang centralized workflow mula submission hanggang verified closure.', 'Iugnay ang problemang ito sa actual findings ninyo; hindi pa ito patunay na nasukat na ang lahat ng delays.'),
('What evidence have you gathered to show that maintenance reporting is currently a problem in the school?', 'Sa kasalukuyang manuscript, inilalarawan namin ang posibleng problema sa informal reporting, ngunit hindi pa nakalatag ang quantified baseline. Kailangan naming suportahan ito ng authorized interviews, observations, at available report records. Kung hindi pa tapos ang data gathering, iyon ang tapat naming sasabihin sa panel.', 'Ihanda ang totoong interview dates, respondent roles, at findings. Huwag mag-imbento ng bilang ng nawawalang reports.'),
('How are facility and equipment concerns currently reported, and where do delays usually occur?', 'Ang process na tinatalakay namin ay reporting sa verbal communication o personal messages. Posibleng maantala ang pagproseso kapag kulang ang detalye, hindi malinaw ang recipient, o walang centralized follow-up record. Iva-validate namin sa school personnel ang actual process at kung saang stage talaga may delay.', 'Ang possible delay ay hypothesis hangga’t hindi kinukumpirma ng actual observation o records.'),
('Who experiences the greatest difficulty in the existing process?', 'Magkakaiba ang difficulty ng bawat role. Ang Reporter ay maaaring walang malinaw na status, ang Property Custodian ay kailangang mag-organize at mag-assign ng concerns, at ang Maintenance Personnel ay nangangailangan ng kumpletong location at issue details. Hindi pa namin iraranggo kung sino ang pinakaapektado nang walang supporting data.', 'Ipaliwanag ang epekto sa bawat role, hindi lamang sa students.'),
('Why is a dedicated application needed when users can report through Messenger, Google Forms, or personal communication?', 'Kayang tumanggap ng reports ng existing tools, pero ang CampusFix ay para sa isang tuloy-tuloy na maintenance workflow: room identification, validation, prioritization, assignment, progress updates, at completion verification. Ang value nito ay ang connected records at accountability ng bawat stage. Kailangan pa rin naming ipakita sa evaluation kung sapat ang benefit para sa school.', 'Huwag sabihing walang tracking capability ang ibang tools; ipaliwanag ang workflow na pinagsama ninyo.'),
('What makes CampusFix different from existing maintenance reporting systems?', 'Hindi namin inaangkin na bago ang QR reporting o maintenance tracking. Ang contribution namin ay ang pag-angkop ng room QR identification, campus location checking, at four-role validation at repair workflow sa pangangailangan ng ESCR. Ipapakita namin ang pagkakaiba gamit ang feature at workflow comparison sa pinakamalapit na related systems.', 'Local adaptation at integration ang defensible na contribution; iwasang sabihing first-ever.'),
('How does each specific objective address the problems identified in your introduction?', 'Ang mobile reporting at QR scanning ay para sa mas kumpletong submission at location details. Ang IT screening ay para sa incomplete, duplicate, o inappropriate reports. Ang custodian interface at maintenance workflow ay para sa prioritization, assignment, at progress monitoring. Ang evaluation objective ay para masuri kung gumagana at katanggap-tanggap ang proposed solution.', 'Maghanda ng problem–objective–feature–test mapping para malinaw ang alignment.')]),
('B  QR codes and location validation', [
('Why did you assign QR codes to rooms rather than to individual pieces of equipment?', 'Room-based ang QR code para isang location code ang magamit sa pagreport ng iba’t ibang registered facilities at equipment sa room. Pagkatapos mag-scan, pipiliin ng Reporter ang affected item. Mas simple ito sa label deployment, ngunit nangangailangan ng malinaw at updated na item records upang hindi malito sa magkaparehong equipment.', 'Hindi sapat ang room QR lang para matukoy ang eksaktong upuan o computer.'),
('What information is stored in the QR code?', 'Ayon sa proposal, ang QR code ay naka-associate sa unique Location ID ng registered room. Ang recommended implementation ay location reference lang ang laman, hindi personal information o buong equipment list. Gagamitin ng application ang reference para kunin sa server ang authorized room at equipment details.', 'Ang eksaktong QR payload o format ay technical decision na dapat i-finalize.'),
('After scanning a room’s QR code, how will a Reporter identify the specific damaged item if several identical items are in that room?', 'Pipili ang Reporter mula sa registered equipment ng room, pero kailangang distinguishable ang bawat record. Ang proposed refinement ay gumamit ng existing asset tag o item label, kasama ang description at placement gaya ng computer station number. Kung hindi pa ito naidisenyo, aaminin naming kailangan itong idagdag sa item-identification rules.', 'Supporting photo at description ay tulong; hindi sila kapalit ng malinaw na item identity.'),
('Who will register rooms and equipment and generate their QR codes?', 'Ang manuscript ay nagsasaad na ireregister ang rooms at equipment at bubuo ng QR codes, pero kailangan pang i-finalize ang exact permission owner. Ang recommendation namin ay school-authorized personnel ang mag-maintain ng location at equipment records, na may malinaw na custodian responsibility. Hindi dapat makapag-create o makapagpalit ng official room records ang ordinaryong Reporter.', 'Kumpirmahin sa school kung IT o Property Custodian ang operator at approver.'),
('What happens if a QR code is damaged, missing, transferred, or placed in the wrong room?', 'Ang proposed handling ay ireport muna ang label problem sa authorized personnel para ma-verify ang room record at mapalitan ang label. Ipapakita rin sa app ang room name pagkatapos ng scan para mapansin ang mismatch. Ang moved o copied label ay hindi awtomatikong napapatunayan ng scan, kaya kailangan pa rin ng physical checks at validation.', 'Wala pang finalized fallback sa manuscript. Huwag mangakong may manual bypass kung hindi pa approved.'),
('If someone takes a picture of a QR code and scans it elsewhere, how will the system handle the report?', 'Kung nasa labas siya ng campus, layunin ng location validation na pigilan ang submission. Pero kung nasa loob pa rin ng campus ang user, maaaring pumasa ang copied QR dahil campus boundary lang ang chine-check. Kaya ang QR at GPS ay supporting controls lamang; kailangan pa rin ng authorized account, evidence, at human review.', 'Huwag sabihing imposible ang fake reports o QR copying.'),
('Why do you need GPS validation if the Reporter has already scanned a room QR code?', 'Ang QR code ay para tukuyin ang registered room, habang ang GPS check ay para suriin kung nasa designated campus area ang user sa oras ng submission. Magkaiba ang kanilang purpose. Hindi nito pinapatunayan nang mag-isa na nasa mismong room ang user o na totoo ang issue.', 'Room reference ang QR; campus presence check ang GPS.'),
('Does GPS validation confirm that the user is inside the campus, or inside the specific room?', 'Campus presence ang intended validation sa proposal. Hindi kami magke-claim ng accurate room-level positioning gamit lamang ang GPS. Ang room ay kinikilala sa scanned QR reference, at ang report details ay ive-verify pa rin ng assigned personnel.', 'Ito ang mahalagang limitasyon na dapat pare-pareho ang sagot ng buong group.'),
('How will you define the campus boundary and the acceptable location accuracy?', 'Hindi pa nakasaad sa manuscript ang final boundary coordinates, geofence shape, at accuracy threshold. Iminumungkahi naming kunin ang verified campus boundary at magsagawa ng field tests sa loob, gilid, at labas ng campus. Doon ibabase ang acceptance rules at handling ng uncertain readings, hindi sa arbitraryong radius.', 'Kailangan pang i-finalize ang boundary, reading freshness, at accuracy requirements.'),
('What happens if a user is inside the campus but the GPS reading places them outside?', 'Kinikilala ito ng scope bilang possible limitation. Ang recommended behavior ay malinaw na error message at retry gamit ang bagong location reading; hindi dapat agad ituring na dishonest ang user. Kung kailangan ng alternative reporting path, dapat aprubado ito ng school at may documented validation, hindi secret bypass.', 'Huwag mag-claim ng guaranteed indoor accuracy.'),
('How will the system handle denied location permission, unavailable GPS, or an inaccurate location reading?', 'Dahil required ang location validation sa proposal, hindi makukumpleto ang normal submission hangga’t hindi valid ang location check. Dapat ipaliwanag ng app kung anong permission o reading ang kailangan at payagan ang retry. Ang fallback procedure ay kailangan pang i-finalize kasama ng school upang may paraan pa ring maipaalam ang concern.', 'Ihiwalay ang proposed app behavior sa existing school reporting channels.')]),
('C  Report validation and maintenance workflow', [
('Why must IT Personnel validate reports before the Property Custodian reviews them? Could this create another source of delay?', 'Sa proposed workflow, IT Personnel ang initial screener ng completeness at appropriateness, at ang Property Custodian ang maintenance decision-maker. Posibleng makatulong ang screening sa pag-organize ng reports, pero posible rin itong maging bottleneck. Kaya kailangang kumpirmahin ang staffing at sukatin ang validation waiting time bago sabihing mas mabilis ang workflow.', 'Hindi dapat mangako ng faster processing dahil lang may dagdag na validation stage.'),
('Have the IT Personnel and Property Custodian agreed to the responsibilities assigned to them?', 'Hindi sapat ang manuscript para patunayang may actual agreement na. Kung wala pa kaming documented confirmation, sasabihin naming proposed responsibilities pa lamang ang mga ito at ipapa-validate namin sa concerned personnel. Isasama namin sa requirements validation ang workload, authority, at availability ng bawat role.', 'Dalhin ang tunay na interview notes o approval kung mayroon; huwag gumawa ng consent.'),
('Is duplicate detection automatic, or will IT Personnel manually identify duplicate reports?', 'Ang nakasaad ay screening feature na tumutulong sa IT Personnel na mag-identify ng possible duplicates. Wala pang tinukoy na automatic matching algorithm o AI detector. Kaya manual review ang defensible na description; maaari itong suportahan ng filtering sa room, equipment, issue, at existing status.', 'Huwag gumamit ng salitang automatic kung manual review pa lang ang scope.'),
('How will you distinguish a duplicate report from a new issue affecting the same equipment?', 'Iche-check ng reviewer ang equipment identity, description, photos, dates, at kung may unresolved report para sa parehong issue. Hindi lahat ng report sa parehong item ay duplicate; maaaring iba ang defect o bagong incident pagkatapos ng closure. Kailangan naming i-document ang decision rules at rejection reason para traceable ang assessment.', 'Parehong equipment ay hindi awtomatikong parehong problema.'),
('Can a Reporter correct an incomplete report, or must they submit another one?', 'Sa kasalukuyang workflow, maaaring ma-reject ang incomplete report; hindi pa malinaw ang edit at resubmission rules. Ang safe answer ay kailangan pa itong i-finalize. Ang recommendation namin ay may malinaw na reason at controlled correction o resubmission na naka-link sa original report para hindi mawala ang history.', 'Huwag sabihing implemented na ang edit feature kung wala pa sa approved scope.'),
('What criteria will the Property Custodian use to determine priority?', 'Ang Property Custodian ang magse-set ng priority ayon sa proposal. Ang recommended criteria ay safety implications, lawak ng affected users, disruption sa classes o operations, at urgency ng defect. Kailangan pang i-finalize ang priority definitions kasama ng school; hindi ang Reporter ang may final authority sa ranking.', 'Emergency incidents ay dadaan pa rin sa existing emergency procedures.'),
('What happens if the assigned Maintenance Personnel is unavailable or cannot perform the repair?', 'Dapat makita ng custodian ang assignment at progress para ma-review ang situation. Ang recommended rule ay puwedeng mag-reassign ang authorized custodian, may reason at retained assignment history. Kung specialized repair ang kailangan, school personnel pa rin ang magdedesisyon; hindi awtomatikong magsasagawa o mag-aapprove ng repair ang app.', 'I-finalize ang reassignment permissions at escalation process.'),
('How will the system represent a task that is waiting for materials or an external technician?', 'Hindi pa kasama ang explicit on-hold status sa listed stages ng manuscript. Sa current design, puwedeng ma-document ang blocker sa progress notes habang unresolved ang task. Mas malinaw kung magkakaroon ng approved waiting-state rule, pero kailangan muna itong i-align sa flowcharts, database, at scope bago ipangakong feature.', 'Hindi kasama sa scope ang procurement at supply inventory.'),
('What is the difference between “Completed” and “Closed”?', 'Completed means naiulat na ng Maintenance Personnel na tapos ang repair at na-upload ang required notes at evidence. Closed means na-review at na-approve na ng Property Custodian ang completion. Kaya hindi sapat na maintenance personnel lang ang magsabing tapos upang official nang maisara ang report.', 'Completed = submitted completion; Closed = custodian-approved completion.'),
('What happens if the Property Custodian rejects the completion evidence?', 'Ayon sa procedures, maaaring ibalik ng Property Custodian ang work for correction. Kailangan magbigay ng reason, pagkatapos ay mag-update at magsumite ulit ng evidence ang maintenance personnel. Hindi dapat manatiling officially closed ang report habang hindi approved; kailangan pang tukuyin ang eksaktong return status sa transition rules.', 'Iayon ang sagot sa flowchart at allowed status transitions.'),
('Can a Reporter dispute a closed report if the problem still exists?', 'Hindi pa explicit sa manuscript ang dispute o reopen feature. Ang recommendation namin ay magkaroon ng controlled review request, kung iaapprove sa scope, at custodian ang magdedesisyon kung reopen o bagong report ang kailangan. Kung walang ganitong feature, dapat may malinaw na school reporting procedure at reference sa previous report.', 'Huwag ipresentang existing feature ang proposed enhancement.'),
('How will overdue or unattended reports be monitored?', 'May dashboard at status records sa proposal para makita ang unresolved reports. Ang recommended monitoring ay gumamit ng submission at update timestamps at filters para sa matagal nang walang action. Hindi pa finalized ang due dates, escalation rules, at automatic reminders, kaya hindi namin aangking may SLA automation na.', 'Status visibility ay hindi garantiya na may personnel o budget para agad umaksyon.')]),
('D  Scope and limitations', [
('You exclude inventory management, but the system stores equipment associated with rooms. Where is the boundary between equipment registration and inventory management?', 'Ang equipment registration ay minimum reference data para maituro kung anong item ang may issue at matingnan ang maintenance history nito. Ang excluded inventory functions ay stock quantities, supply availability, movement tracking, at consumption. Kailangan naming panatilihing malinaw ang boundary na ito sa modules at database documentation.', 'Maintenance reference list ang sakop; hindi full inventory lifecycle.'),
('How will equipment records be updated when an item is moved or removed?', 'Kailangan ng authorized update sa room association o active status upang tama ang reporting choices. Ang recommended approach ay panatilihin ang historical report references kahit ma-update ang current location o ma-retire ang item. Hindi nito ibig sabihing magdadagdag kami ng full movement inventory; administrative correction lang ng reporting reference.', 'I-finalize kung sino ang puwedeng mag-update at paano mapapanatili ang history.'),
('Why are procurement, repair budgeting, and maintenance supplies excluded?', 'Nilimitahan namin ang project sa reporting, validation, assignment, monitoring, at completion verification upang manageable at malinaw ang development at evaluation. Procurement at financial processing ay may ibang approvals at data requirements. Maaaring mag-note ng repair blocker sa system, pero ang actual purchase at funding decisions ay nasa existing school process.', 'Ang cost-benefit analysis ng project ay hindi app budgeting module.'),
('What happens if a user submits an emergency through CampusFix even though emergency response is outside your scope?', 'Hindi dapat hintayin ng user ang normal maintenance queue kapag may immediate danger. Ang proposal ay naglilimita sa CampusFix bilang maintenance reporting system; existing school emergency procedures ang dapat sundin. Ang recommended UI ay may malinaw na reminder tungkol dito, at school-approved handling para sa mistakenly submitted emergency reports.', 'Hindi dapat ipangakong monitored 24/7 o may guaranteed emergency dispatch.'),
('Can users submit reports without internet access?', 'Walang offline submission capability na nakasaad sa manuscript. Internet ang kailangan para makipag-communicate ang app sa server at database at makumpleto ang report submission. Maaari naming i-consider ang local draft sa future, pero hindi ito dapat ipresentang existing o approved function.', 'Offline draft at successful server submission ay magkaiba.'),
('Why did you choose a mobile application instead of a responsive website?', 'Mobile-first ang proposed workflow dahil ginagamit ang camera para sa QR scanning at photos at ang device location habang nagrereport sa campus. Gayunman, maaaring gawin din ng responsive web app ang ilan sa mga ito, kaya hindi namin sasabihing impossible iyon. Ang mobile choice ay dapat suportado ng target-device access, user needs, at testing sa Android at iOS.', 'Ipaliwanag ang practical fit; huwag gawing unsupported claim ang superiority.')]),
('E  Technical design and security', [
('What programming language, framework, database, and hosting platform will you use, and why?', 'Hindi pa final ang exact technology stack sa Technical Specifications. Ang requirements namin ay cross-platform mobile support, camera at location integration, secure authentication, relational records, photo storage, at notifications. Bago ang final proposal defense, kailangan naming pumili ng konkretong stack at ipaliwanag ang fit nito sa team skills, deployment cost, at maintenance.', 'Huwag basta sabihin na React Native, Firebase, o ibang tool ang official choice kung hindi pa napagdesisyunan.'),
('How do the presentation, application, and database tiers communicate?', 'Ang mobile app ang presentation tier at magpapadala ito ng authorized requests sa application tier sa pamamagitan ng API. Doon gagawin ang business rules tulad ng report validation at allowed status changes, saka makikipag-ugnayan sa database at attachment storage. Dapat bumalik sa app ang result o malinaw na error; hindi dapat direktang may unrestricted database access ang users.', 'Three-tier architecture ay separation of responsibilities, hindi awtomatikong tatlong physical servers.'),
('How will you prevent a Reporter from accessing functions intended for IT Personnel or the Property Custodian?', 'Role-based access ang proposed control. Dapat i-check ng server ang authenticated account at permission sa bawat request, hindi lang itago ang buttons sa screen. Ite-test namin ang unauthorized direct requests at cross-account access upang matiyak na hindi makapag-assign o makapag-close ng reports ang ordinaryong Reporter.', 'Proposed control ito; actual security testing pa ang kailangan.'),
('How will you verify that registered users are authorized members of the school?', 'Authorized users lang ang scope, ngunit hindi pa detailed ang enrollment at account approval mechanism sa manuscript. Kailangan naming pumili ng school-approved process, gaya ng admin-approved accounts o verified institutional records. Ang role assignment ay dapat controlled ng authorized administrator at hindi basta pinipili ng user sa registration.', 'Kumpirmahin kung may usable institutional email o official account list bago ito ipangako.'),
('Who can view report photos, account information, and location information?', 'Dapat nakabase sa assigned role at operational need ang access. Ang Reporter ay makakakita ng sarili niyang reports, habang ang concerned reviewers at assigned maintenance personnel ay makakakita ng impormasyong kailangan sa kanilang task. Hindi dapat public ang personal o location data; kailangan pang i-finalize ang field-level access matrix.', 'Hindi lahat ng staff role ay kailangang may access sa lahat ng user data.'),
('What location information will you retain after submission, and for how long?', 'Malinaw sa proposal na submission-time check lang ito at walang continuous tracking. Hindi pa final ang stored fields at retention duration. Ang recommendation namin ay minimum necessary validation evidence lang ang itago, at iayon ang retention at deletion process sa approved institutional policy at project needs.', 'Huwag mag-claim ng exact retention period o legal compliance certification na wala pang basis.'),
('How will you prevent unauthorized changes to report statuses and maintenance records?', 'Ang proposed safeguards ay server-side role checks, allowed status transitions, at validation ng assignment at ownership. Recommended din ang audit trail na may actor, timestamp, at change details para traceable ang actions. Kailangan itong isama sa final technical design at tests bago sabihing fully implemented at secure.', 'Halimbawa: hindi puwedeng mag-close ang maintenance account kung custodian approval ang required.'),
('What happens if a photo upload fails or the user accidentally submits the same report twice?', 'Dapat hindi magpakita ng successful submission hangga’t hindi confirmed ng server ang required report at attachment handling. Recommended ang clear retry, submission identifier, at duplicate-request protection upang hindi lumikha ng dalawang report sa retry. Wala pang final failure-handling design, kaya kailangan itong i-document at i-test bilang reliability scenario.', 'Duplicate network request at dalawang magkahiwalay na report tungkol sa parehong issue ay magkaibang problema.'),
('How will the system recover from server failure or data loss?', 'May backup procedures na binabanggit sa ethical safeguards, pero wala pang detailed recovery plan. Kailangan naming tukuyin ang backup schedule, protected storage, restore steps, at responsible person. Dapat subukan ang restore ng database at attachments; ang pagkakaroon lang ng backup file ay hindi pa patunay na makakarecover.', 'Huwag magbanggit ng guaranteed recovery time kung hindi pa nasusukat.'),
('Who will maintain the application and manage accounts after the researchers graduate?', 'Kailangan ng formal turnover arrangement sa school. Ang recommendation namin ay designated IT personnel para sa technical administration at authorized custodian para sa operational records, pero dapat munang kumpirmahin ang acceptance at responsibilities. Isasama sa turnover ang documentation, account access process, deployment details, at maintenance cost requirements.', 'Hindi pa school commitment ang recommendation ng researchers.')]),
('F  Methodology and evaluation', [
('Why did you choose the Waterfall model for CampusFix?', 'Pinili namin ang Waterfall dahil ang proposal ay may defined scope, roles, at workflow na maaaring idokumento sa sequential development phases. Makakatulong ito sa requirements, design, implementation, at testing deliverables ng capstone. Gayunman, kailangang ma-validate nang maaga ang requirements dahil mas mahal baguhin ang design kapag malayo na ang development.', 'Huwag sabihing bawal ang anumang feedback o correction sa Waterfall.'),
('What will you do if users request a major change after the requirements and design phases?', 'Idodokumento namin ang requested change, dahilan, at epekto nito sa scope, schedule, design, at tests. Ipapareview muna ito sa adviser at authorized stakeholder bago tanggapin. Kung approved, ia-update namin ang affected documents at implementation at uulitin ang relevant validation; kung out of scope, ilalagay bilang future recommendation.', 'Hindi automatic acceptance o automatic rejection ang change handling.'),
('How many respondents will participate, and how will you select them from each user group?', 'Wala pang exact sample size at sampling method sa manuscript. Kailangan naming ibatay ang bilang sa actual school population, available personnel, at evaluation purpose, habang may representation ang bawat role. Para sa small specialized groups, maaaring isama ang lahat ng available authorized personnel; para sa Reporters, kailangan ng justified selection plan.', 'I-finalize sa adviser ang sample, inclusion criteria, at recruitment. Huwag mag-imbento ng n=30 o n=100.'),
('How will you evaluate Functional Suitability, Usability, Reliability, and Performance Efficiency?', 'Functional suitability ay susuriin sa pag-complete ng required workflows; usability sa task performance at user feedback; reliability sa successful at failed-operation scenarios; at performance efficiency sa measured response at upload times under stated conditions. Ang user ratings ay magiging bahagi ng evaluation, pero hindi kapalit ng objective technical tests.', 'Kailangan pang i-finalize ang instruments, metrics, at criteria bago mangolekta ng results.'),
('Which aspects require actual technical measurements rather than user opinions alone?', 'Kailangang masukat ang response time, upload behavior, error rate, successful report submission, at consistency ng stored status at records. Kailangan ding i-test ang permission enforcement at behavior kapag pumalya ang connection o location reading. User opinion ay mahalaga sa ease of use at acceptability, pero hindi nito mapapatunayan ang security o speed nang mag-isa.', 'I-record ang device, network conditions, workload, at test procedure.'),
('How will you test QR scanning, location validation, and report submission under different conditions?', 'Maghahanda kami ng normal at failure scenarios: valid at invalid QR, malinaw at mahirap basahing label, inside at outside campus readings, denied permissions, weak connection, at failed upload. Ico-compare ang expected at actual outcome at ire-record ang errors. Ang test sites at devices ay dapat documented upang reproducible ang evaluation.', 'Controlled at authorized tests lamang; huwag mag-claim na tapos na ang testing.'),
('How will you verify compatibility on both Android and iOS?', 'Kailangan naming gumamit ng actual representative Android at iOS devices at documented OS versions para sa core workflows. Ite-test ang login, permissions, QR scan, photo attachment, location validation, notifications, at task updates. Hindi sapat na cross-platform ang framework para sabihing verified na ang parehong platform.', 'Wala pang iOS testing device provision sa cost table; ayusin ang access plan.'),
('What criteria will determine whether the system passes User Acceptance Testing?', 'Iba-base ang acceptance sa approved requirements at role-specific scenarios. Dapat makumpleto ang critical end-to-end tasks, tama ang permissions at records, at walang unresolved critical defects; ang survey threshold ay kailangan pang aprubahan at idokumento bago ang UAT. Hindi namin pipiliin ang passing score pagkatapos makita ang results.', 'Maghanda ng test cases na may expected output, actual output, at stakeholder sign-off.'),
('How will you demonstrate improvement over the current reporting process?', 'Kailangan muna ng baseline sa current process, gaya ng reporting time, missing required details, follow-up effort, at record retrieval time. Iko-compare namin ito sa equivalent CampusFix tasks under documented conditions. Kung wala pang actual deployment evidence, initial usability at technical findings lang ang maaari naming ireport, hindi proven school-wide improvement.', 'Ihiwalay ang reporting efficiency sa actual repair speed na nakadepende sa resources.'),
('What will you do if users give positive ratings but actual testing reveals slow or unreliable performance?', 'Iuulat namin ang parehong findings at hindi namin tatakpan ang technical failures gamit ang positive survey scores. Aalamin at aayusin ang cause, pagkatapos ay uulitin ang affected tests. Kung hindi maayos sa project period, idodokumento namin ang limitation at epekto nito sa acceptance at recommendations.', 'Magkaibang ebidensiya ang acceptability at actual technical quality.')]),
('G  Related studies and financial feasibility', [
('Which related study is closest to CampusFix, and what specific gap does your project address?', 'Batay sa review sa manuscript, malapit ang study nina Gastiadi, Kallista, at Dinimaharawati tungkol sa QR reporting at academic facility maintenance. Ang proposed contribution namin ay ang ESCR-specific integration ng room QR, campus location validation, at four-role review at closure process. Kailangan ang full-text comparison bago mag-claim na wala ang mga feature na ito sa existing study.', 'Manuscript-based ito; hindi independent verification ng publication o ng buong feature set.'),
('How did your reviewed studies influence your features and workflow?', 'Ang QR-related studies ay naging basehan sa location identification, ang facility-management literature sa centralized records at maintenance coordination, at location-aware references sa submission-time campus check. Ginamit namin ang concepts na iyon sa pagdisenyo ng proposed workflow. Hindi ibig sabihin nito na ang effectiveness ng ibang system ay automatic na magiging result ng CampusFix.', 'Pumili ng 2–3 tunay na nabasang references at ipaliwanag ang specific influence nila.'),
('What is your basis for the estimated ₱96,000 annual benefit?', 'Ang ₱96,000 ay total ng six estimated benefit categories sa manuscript, hindi actual measured savings. Kailangan pa naming ipakita ang assumptions at source data ng bawat estimate, gaya ng report volume, time saved, at assigned hourly cost. Kung wala pa ang basis, dapat naming tawaging preliminary estimate at i-revise pagkatapos ng validation.', 'Huwag sabihing guaranteed income o actual savings ang ₱96,000.'),
('How did you convert time savings into monetary values?', 'Ang defensible approach ay annual number of relevant activities × average time saved per activity in hours × justified hourly labor cost. Dapat may baseline at measured or clearly identified assumed time savings. Dahil wala pang full derivation sa manuscript, kailangan naming idagdag ang computation per benefit category bago idepensang established na ang values.', 'Time value ay estimated productivity benefit; hindi laging actual cash savings.'),
('Are any benefit categories measuring the same savings twice?', 'Posible, lalo na sa follow-up savings, record retrieval, at coordination kung parehong oras ang na-count. Kailangan naming mag-define ng mutually distinct activities at bilangin ang bawat saved unit of time nang isang beses lamang. Kung may overlap, babawasan o pagsasamahin namin ang category at irerecompute ang total benefit.', 'Mas kapani-paniwala ang conservative estimate kaysa inflated na ROI.'),
('Why does the cost table show ₱65,299 while the ROI computation uses ₱62,300?', 'May inconsistency sa original computation at kailangan itong itama. Gamit ang listed cost na ₱65,299 at estimated benefit na ₱96,000, ang net estimated benefit ay ₱30,701. Ang computation ay (₱30,701 / ₱65,299) × 100 = 47.02%, subject pa rin sa validation ng costs at benefits.', 'Tawaging estimated first-year ROI; huwag gamitin ang lumang 54.09% o ipangakong pareho kada taon.'),
('Why are equipment purchases included if the researchers or school already own those devices?', 'Kailangan naming linawin kung ang table ay actual additional expenditure o total resource requirement. Kung existing na ang laptop o phones at walang bagong purchase, hindi dapat automatic na buong purchase price ang incremental cash cost. Maaari silang ilista bilang existing resources o gumamit ng justified allocation, at ia-update ang ROI ayon sa napiling consistent costing basis.', 'Ihiwalay ang one-time capital costs sa recurring operating costs.'),
('Where is the provision for iOS testing, given that the equipment table lists Android smartphones?', 'May gap ang current cost at testing plan dahil Android devices lang ang listed, pero Android at iOS ang objective. Kailangan naming mag-secure ng actual iOS test access, gaya ng authorized borrowed device, at idokumento iyon; kung may additional expense, isasama sa costs. Kung hindi talaga available, kailangan i-review ang scope kasama ng adviser.', 'Huwag mag-claim na may iPhone testing na kung wala pa.'),
('Who will pay for hosting, storage, and ongoing maintenance after deployment?', 'Hindi pa nakasaad ang confirmed funding owner sa manuscript. Kailangan ng school-approved sustainability plan na may recurring hosting, storage, support, at account administration costs. Ang listed allowance ay estimate lamang at hindi katumbas ng school commitment; dapat may agreed turnover at funding arrangement bago ang long-term deployment.', 'Ipakita ang first-year at succeeding-year costs nang hiwalay; huwag ipangakong free forever.')])]

doc=Document()
sec=doc.sections[0]
sec.top_margin=sec.bottom_margin=Inches(.7)
sec.left_margin=sec.right_margin=Inches(.8)
sec.page_width=Inches(8.27); sec.page_height=Inches(11.69)
for name in ['Normal','Title','Subtitle','Heading 1','Heading 2']:
    st=doc.styles[name]; st.font.name='Arial'; st.font.color.rgb=RGBColor(0,0,0)
doc.styles['Normal'].font.size=Pt(10.5)
doc.styles['Normal'].paragraph_format.space_after=Pt(6)
doc.styles['Normal'].paragraph_format.line_spacing=1.1
doc.styles['Title'].font.size=Pt(26)
doc.styles['Heading 1'].font.size=Pt(16)
doc.styles['Heading 2'].font.size=Pt(11)
doc.styles['Heading 2'].paragraph_format.space_before=Pt(12)
doc.styles['Heading 2'].paragraph_format.keep_with_next=True
doc.add_heading('CampusFix Defense Reviewer',0)
doc.add_paragraph('65 possible panelist questions with Taglish sample answers',style='Subtitle')
doc.add_paragraph('Para sa proposal defense ng CampusFix QR Based School Facility and Equipment Maintenance Reporting and Tracking System.')
doc.add_heading('Paano gamitin ang reviewer',1)
doc.add_paragraph('Basahin ang tanong, sagutin muna sa sarili mong salita, at saka i-compare sa sample answer. Ang mga sagot ay para sa proposal stage: gumamit ng “proposed,” “plan,” o “will” hangga’t hindi pa developed, tested, o approved ang isang feature. Aralin ang dahilan ng sagot sa halip na kabisaduhin bawat sentence.')
doc.add_paragraph('Ang “Tandaan” sa bawat item ay study note para sa paghahanda. Ang recommended controls at refinements ay kailangang i-finalize sa team, adviser, at school; hindi sila awtomatikong bahagi ng approved scope o existing implementation.')
doc.add_heading('Unahin bago ang defense',1)
for s in ['Magdala ng actual evidence ng school reporting process at stakeholder validation.', 'I-finalize ang technology stack, account verification, GPS boundary rules, at workflow exceptions.', 'Kumpletuhin ang respondent count, sampling plan, evaluation metrics, at UAT criteria.', 'Itama ang ROI sa 47.02% gamit ang current cost table at i-validate ang benefit assumptions.', 'Kumpirmahin ang iOS testing access, school turnover, at recurring funding plan.']:
    doc.add_paragraph(s,style='List Bullet')
doc.add_heading('Mahalagang workflow',1)
doc.add_paragraph('Reporter → IT validation → Property Custodian review and assignment → Maintenance work and completion submission → Property Custodian verification → Closure.')
doc.add_paragraph('Completed: na-submit ng maintenance personnel ang completion. Closed: na-verify at na-approve na ng Property Custodian. Ang QR ay room reference; ang GPS check ay campus presence validation lamang.')
doc.add_paragraph('Reference: FINALMANU02CAMPUSFIX.docx, supplied CampusFix proposal manuscript, October 2026. Ang reviewer ay hindi independent verification ng bibliography, legal compliance, o actual school results.')
idx=0
for title,items in sections:
    doc.add_page_break(); doc.add_heading(title,1)
    for question,answer,note in items:
        idx+=1
        doc.add_heading(f'{idx}. {question}',2)
        p=doc.add_paragraph(); p.add_run('Sample answer: ').bold=True; p.add_run(answer)
        p=doc.add_paragraph(); p.paragraph_format.space_after=Pt(8)
        r=p.add_run('Tandaan: '); r.bold=True; r.font.size=Pt(9)
        r=p.add_run(note); r.italic=True; r.font.size=Pt(9)
assert idx==65,idx
footer=sec.footer.paragraphs[0]; footer.alignment=2
r=footer.add_run('CampusFix reviewer  |  '); r.font.size=Pt(8)
fld=OxmlElement('w:fldSimple'); fld.set(qn('w:instr'),'PAGE'); footer._p.append(fld)
doc.save(OUT)
print(OUT)
